RACE = [k for k in qb.Q if k not in FIRST]
DAILY = {k for row in qb.DAYS for k in row}
assert not (set(RACE) & DAILY), "a race question is also a daily question"
DAILY_LETTERS = {(q["pattern"][0], q["pattern"][1]) for k, q in qb.Q.items() if k in DAILY and "pattern" in q}
assert not any((qb.Q[k]["pattern"][0], qb.Q[k]["pattern"][1]) in DAILY_LETTERS for k in RACE if "pattern" in qb.Q[k]), "a race letter puzzle repeats a daily one"
